    "parameter_morphing_json": "{\"description\": \"自变量探索与零点目标滑块\", \"sliders\": [{\"id\": \"var_x\", \"nameZh\": \"自变量 x\", \"nameEn\": \"Variable x\", \"min\": -5.0, \"max\": 5.0, \"default\": 2.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"var_y\", \"nameZh\": \"自变量 y\", \"nameEn\": \"Variable y\", \"min\": -5.0, \"max\": 5.0, \"default\": -1.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"target_x0\", \"nameZh\": \"零点目标 x₀\", \"nameEn\": \"Target x0\", \"min\": -3.0, \"max\": 3.0, \"default\": 2.0, \"step\": 1.0, \"unit\": \"\"}, {\"id\": \"target_y0\", \"nameZh\": \"零点目标 y₀\", \"nameEn\": \"Target y0\", \"min\": -3.0, \"max\": 3.0, \"default\": -1.0, \"step\": 1.0, \"unit\": \"\"}]}",
