    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"perimeter\", \"nameZh\": \"周长与几何约束干扰\", \"nameEn\": \"Perimeter Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [-4, -4], \"to\": [4, -4], \"color\": \"var(--border-subtle)\"}]}], \"coreSkeleton\": {\"nameZh\": \"非负数零和方程组骨架\", \"nameEn\": \"Non-negative Zero-Sum Skeleton\", \"primaryElements\": [\"P_target\", \"P_curr\"], \"invariants\": [{\"id\": \"term1_abs\", \"type\": \"formula\", \"deps\": [\"var_x\", \"target_x0\"], \"formula\": \"abs(var_x - target_x0)\", \"labelZh\": \"第一项绝对值 |x - x₀|\", \"labelEn\": \"Term 1 |x - x0|\"}, {\"id\": \"term2_sq\", \"type\": \"formula\", \"deps\": [\"var_y\", \"target_y0\"], \"formula\": \"(var_y - target_y0)^2\", \"labelZh\": \"第二项偶次幂 (y - y₀)²\", \"labelEn\": \"Term 2 (y - y0)^2\"}, {\"id\": \"sum_nonneg\", \"type\": \"formula\", \"deps\": [\"var_x\", \"var_y\", \"target_x0\", \"target_y0\"], \"formula\": \"abs(var_x - target_x0) + (var_y - target_y0)^2\", \"labelZh\": \"非负数总和 S\", \"labelEn\": \"Total Non-negative Sum S\", \"state_label\": \"abs(var_x - target_x0) + (var_y - target_y0)^2 == 0 ? '达到唯一解 (S = 0)' : '严格正定 (S > 0)'\"}]}}",
