    "carrier_morphing_json": "{\"options\": [{\"id\": \"cross_multiplication_grid\", \"nameZh\": \"十字相乘系数网络载体\", \"nameEn\": \"Cross Multiplication Network Carrier\", \"points\": [{\"id\": \"A1\", \"name\": \"a1\", \"x\": -2, \"y\": 2, \"color\": \"#38bdf8\", \"size\": 5, \"isFixed\": true}, {\"id\": \"A2\", \"name\": \"a2\", \"x\": -2, \"y\": -2, \"color\": \"#38bdf8\", \"size\": 5, \"isFixed\": true}, {\"id\": \"C1\", \"name\": \"c1\", \"x\": 2, \"y\": 2, \"color\": \"#f59e0b\", \"size\": 5, \"isFixed\": true}, {\"id\": \"C2\", \"name\": \"c2\", \"x\": 2, \"y\": -2, \"color\": \"#f59e0b\", \"size\": 5, \"isFixed\": true}, {\"id\": \"Center\", \"name\": \"×(交叉中心)\", \"x\": 0, \"y\": 0, \"color\": \"#34c759\", \"size\": 4, \"isFixed\": true}]}, {\"id\": \"group_factoring\", \"nameZh\": \"分组分解法矩形载体\", \"nameEn\": \"Group Factoring Rectangle Carrier\", \"points\": [{\"id\": \"O\", \"name\": \"O\", \"x\": 0, \"y\": 0, \"color\": \"#64748b\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P1\", \"name\": \"P1\", \"x\": 2, \"y\": 0, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P2\", \"name\": \"P2\", \"x\": 2, \"y\": 3, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P3\", \"name\": \"P3\", \"x\": 0, \"y\": 3, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P4\", \"name\": \"P4\", \"x\": 5, \"y\": 3, \"color\": \"#f59e0b\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P5\", \"name\": \"P5\", \"x\": 5, \"y\": 0, \"color\": \"#f59e0b\", \"size\": 4, \"isFixed\": true}]}], \"default\": \"cross_multiplication_grid\"}",
