    "posture_morphing_json": "{\"modes\": [{\"id\": \"standard\", \"nameZh\": \"标准十字相乘态\", \"nameEn\": \"Standard Cross State\", \"rotationDeg\": 0, \"reflected\": false}, {\"id\": \"transposed\", \"nameZh\": \"因子对偶转置态\", \"nameEn\": \"Transposed Dual State\", \"rotationDeg\": 0, \"reflected\": true}], \"default\": \"standard\"}",
    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"diagonal\", \"nameZh\": \"辅助交叉对角线干扰\", \"nameEn\": \"Diagonal Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [-3, -3], \"to\": [3, 3], \"color\": \"var(--border-subtle)\"}]}], \"coreSkeleton\": {\"nameZh\": \"双十字交叉联动骨架\", \"nameEn\": \"Cross Multiplication Skeleton\", \"primaryElements\": [\"A1\", \"A2\", \"C1\", \"C2\"], \"invariants\": [{\"id\": \"coeff_a\", \"type\": \"formula\", \"deps\": [\"factor_a1\", \"factor_a2\"], \"formula\": \"factor_a1 * factor_a2\", \"labelZh\": \"二次项系数 a = a₁ · a₂\", \"labelEn\": \"Leading Coefficient a\"}, {\"id\": \"coeff_c\", \"type\": \"formula\", \"deps\": [\"factor_c1\", \"factor_c2\"], \"formula\": \"factor_c1 * factor_c2\", \"labelZh\": \"常数项 c = c₁ · c₂\", \"labelEn\": \"Constant Term c\"}, {\"id\": \"coeff_b_cross\", \"type\": \"formula\", \"deps\": [\"factor_a1\", \"factor_a2\", \"factor_c1\", \"factor_c2\"], \"formula\": \"factor_a1 * factor_c2 + factor_a2 * factor_c1\", \"labelZh\": \"一次项交叉和 b = a₁c₂ + a₂c₁\", \"labelEn\": \"Cross Sum b = a1*c2 + a2*c1\"}, {\"id\": \"factored_delta\", \"type\": \"formula\", \"deps\": [\"factor_a1\", \"factor_a2\", \"factor_c1\", \"factor_c2\"], \"formula\": \"(factor_a1 * factor_c2 + factor_a2 * factor_c1)^2 - 4 * (factor_a1 * factor_a2) * (factor_c1 * factor_c2)\", \"labelZh\": \"因式分解判别式 Δ = b² - 4ac\", \"labelEn\": \"Factoring Discriminant Delta\"}]}}",
