    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"asymptote\", \"nameZh\": \"渐近线与非定义域干扰\", \"nameEn\": \"Asymptote Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [2, -6], \"to\": [2, 6], \"color\": \"var(--border-subtle)\"}]}], \"coreSkeleton\": {\"nameZh\": \"分式方程增根洞点与同解变换骨架\", \"nameEn\": \"Rational Extraneous Root Skeleton\", \"primaryElements\": [\"Hole\", \"P_root\"], \"invariants\": [{\"id\": \"common_denom\", \"type\": \"formula\", \"deps\": [\"var_x\", \"param_root\"], \"formula\": \"var_x - param_root\", \"labelZh\": \"最简公分母值 (x - x_hole)\", \"labelEn\": \"Common Denominator (x - x0)\", \"state_label\": \"abs(var_x - param_root) < 0.001 ? '[警报] 触发增根警报: 分母为零无定义，该根舍去！' : '合法实数根'\"}, {\"id\": \"telescope_sum\", \"type\": \"formula\", \"deps\": [\"telescope_n\"], \"formula\": \"1 - 1 / (telescope_n + 1)\", \"labelZh\": \"裂项求和累加值 S_n = 1 - 1/(n+1)\", \"labelEn\": \"Telescoping Sum Sn\"}, {\"id\": \"residual_eps\", \"type\": \"formula\", \"deps\": [\"telescope_n\"], \"formula\": \"1 / (telescope_n + 1)\", \"labelZh\": \"残余未消项 ε = 1/(n+1)\", \"labelEn\": \"Residual Term\"}]}}",
