    "carrier_morphing_json": "{\"options\": [{\"id\": \"median_doubling_plane\", \"nameZh\": \"倍长中线SAS全等三角形载体\", \"nameEn\": \"Median Doubling SAS Congruence Carrier\", \"points\": [{\"id\": \"D\", \"name\": \"D(中点)\", \"x\": 0, \"y\": 0, \"color\": \"#34c759\", \"size\": 5, \"isFixed\": true}, {\"id\": \"B\", \"name\": \"B\", \"x\": -4, \"y\": 0, \"color\": \"#38bdf8\", \"size\": 5, \"isFixed\": true}, {\"id\": \"C\", \"name\": \"C\", \"x\": 4, \"y\": 0, \"color\": \"#38bdf8\", \"size\": 5, \"isFixed\": true}, {\"id\": \"A\", \"name\": \"A\", \"x\": -1, \"y\": 5, \"color\": \"#f59e0b\", \"size\": 5, \"isFixed\": false}, {\"id\": \"E\", \"name\": \"E(倍长点)\", \"x\": 1, \"y\": -5, \"color\": \"#a855f7\", \"size\": 5, \"isFixed\": false}]}, {\"id\": \"obtuse_median_doubling\", \"nameZh\": \"钝角三角形倍长中线载体\", \"nameEn\": \"Obtuse Triangle Median Doubling\", \"points\": [{\"id\": \"D\", \"name\": \"D\", \"x\": 0, \"y\": 0, \"color\": \"#34c759\", \"size\": 5, \"isFixed\": true}, {\"id\": \"B\", \"name\": \"B\", \"x\": -3, \"y\": 0, \"color\": \"#38bdf8\", \"size\": 5, \"isFixed\": true}, {\"id\": \"C\", \"name\": \"C\", \"x\": 3, \"y\": 0, \"color\": \"#38bdf8\", \"size\": 5, \"isFixed\": true}, {\"id\": \"A\", \"name\": \"A\", \"x\": -4, \"y\": 3, \"color\": \"#f59e0b\", \"size\": 5, \"isFixed\": false}, {\"id\": \"E\", \"name\": \"E\", \"x\": 4, \"y\": -3, \"color\": \"#a855f7\", \"size\": 5, \"isFixed\": false}]}], \"default\": \"median_doubling_plane\"}",
    "parameter_morphing_json": "{\"description\": \"倍长中线延伸比例与顶点 A 坐标\", \"sliders\": [{\"id\": \"extend_ratio\", \"nameZh\": \"中线延伸倍率\", \"nameEn\": \"Extension Ratio\", \"min\": 0.5, \"max\": 2.0, \"default\": 1.0, \"step\": 0.1, \"unit\": \"\"}, {\"id\": \"vertex_ax\", \"nameZh\": \"顶点 A 横坐标\", \"nameEn\": \"Vertex A X\", \"min\": -4.0, \"max\": 4.0, \"default\": -1.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"vertex_ay\", \"nameZh\": \"顶点 A 纵坐标\", \"nameEn\": \"Vertex A Y\", \"min\": 2.0, \"max\": 7.0, \"default\": 5.0, \"step\": 0.5, \"unit\": \"\"}]}",
    "posture_morphing_json": "{\"modes\": [{\"id\": \"standard\", \"nameZh\": \"标准态 (底边水平)\", \"nameEn\": \"Standard (Base Horizontal)\", \"rotationDeg\": 0, \"reflected\": false}, {\"id\": \"rot_90\", \"nameZh\": \"旋转 90°\", \"nameEn\": \"Rotated 90°\", \"rotationDeg\": 90, \"reflected\": false}, {\"id\": \"reflected\", \"nameZh\": \"镜像翻折\", \"nameEn\": \"Reflection\", \"rotationDeg\": 0, \"reflected\": true}], \"default\": \"standard\"}",
    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"d1\", \"nameZh\": \"多边形干扰背景线\", \"nameEn\": \"Background Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [-5, -2], \"to\": [5, 4], \"color\": \"var(--border-subtle)\"}]}], \"coreSkeleton\": {\"nameZh\": \"倍长中线构造全等中心对称骨架\", \"nameEn\": \"Median Doubling Congruence Skeleton\", \"primaryElements\": [\"A\", \"B\", \"C\", \"D\", \"E\"], \"invariants\": [{\"id\": \"len_ad\", \"type\": \"distance\", \"deps\": [\"A\", \"D\"], \"formula\": \"AD = {val}\", \"labelZh\": \"原中线 AD 长度\", \"labelEn\": \"Original Median AD\"}, {\"id\": \"len_de\", \"type\": \"distance\", \"deps\": [\"D\", \"E\"], \"formula\": \"DE = {val}\", \"labelZh\": \"倍长延伸段 DE 长度\", \"labelEn\": \"Doubled Segment DE\"}, {\"id\": \"len_ab\", \"type\": \"distance\", \"deps\": [\"A\", \"B\"], \"formula\": \"AB = {val}\", \"labelZh\": \"原边长 AB\", \"labelEn\": \"Original Side AB\"}, {\"id\": \"len_ce\", \"type\": \"distance\", \"deps\": [\"C\", \"E\"], \"formula\": \"CE = {val}\", \"labelZh\": \"全等转化边 CE\", \"labelEn\": \"Transferred Side CE\"}, {\"id\": \"congruence_status\", \"type\": \"formula\", \"deps\": [\"extend_ratio\"], \"formula\": \"abs(extend_ratio - 1.0)\", \"labelZh\": \"SAS 全等判定残差\", \"labelEn\": \"SAS Congruence Residual\", \"state_label\": \"abs(extend_ratio - 1.0) < 0.01 ? '△ABD ≌ △ECD (SAS 严格全等成立)' : '未完全倍长'\"}]}}",
