    "parameter_morphing_json": "{\"description\": \"动点 E、F 截线位置与正方形边长\", \"sliders\": [{\"id\": \"pos_e\", \"nameZh\": \"动点 E 截线位置\", \"nameEn\": \"Point E Position\", \"min\": 1.0, \"max\": 5.0, \"default\": 2.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"pos_f\", \"nameZh\": \"动点 F 截线位置\", \"nameEn\": \"Point F Position\", \"min\": 1.0, \"max\": 5.0, \"default\": 1.5, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"side_len\", \"nameZh\": \"基准正方形边长\", \"nameEn\": \"Square Side Length\", \"min\": 4.0, \"max\": 8.0, \"default\": 6.0, \"step\": 1.0, \"unit\": \"\"}]}",
    "posture_morphing_json": "{\"modes\": [{\"id\": \"standard\", \"nameZh\": \"标准态 (底边水平)\", \"nameEn\": \"Standard Horizontal\", \"rotationDeg\": 0, \"reflected\": false}, {\"id\": \"rot_90\", \"nameZh\": \"正交旋转 90°\", \"nameEn\": \"Rotated 90°\", \"rotationDeg\": 90, \"reflected\": false}, {\"id\": \"reflected\", \"nameZh\": \"轴对称翻折\", \"nameEn\": \"Reflection\", \"rotationDeg\": 0, \"reflected\": true}], \"default\": \"standard\"}",
    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"d1\", \"nameZh\": \"对角线与外部干扰线\", \"nameEn\": \"Diagonal Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [0, 6], \"to\": [6, 0], \"color\": \"var(--border-subtle)\"}]}], \"coreSkeleton\": {\"nameZh\": \"截长补短构造全等骨架\", \"nameEn\": \"Cut and Fill Congruence Skeleton\", \"primaryElements\": [\"A\", \"B\", \"C\", \"D\", \"E\", \"F\", \"G\"], \"invariants\": [{\"id\": \"inv_sum_diff_equality\", \"type\": \"relation\", \"deps\": [\"B\", \"E\", \"D\", \"F\"], \"formula\": \"BE + DF = EF\", \"labelZh\": \"线段和差守恒: BE + DF = EF\", \"labelEn\": \"Segment Sum Invariant: BE + DF = EF\", \"tolerance\": 0.001, \"isConstant\": true}, {\"id\": \"inv_congruence_side\", \"type\": \"relation\", \"deps\": [\"A\", \"G\", \"F\"], \"formula\": \"AG = AF\", \"labelZh\": \"全等对应边相等: AG = AF\", \"labelEn\": \"Congruent Side: AG = AF\", \"tolerance\": 0.001, \"isConstant\": true}, {\"id\": \"angle_half\", \"type\": \"angle\", \"deps\": [\"E\", \"A\", \"F\"], \"formula\": \"∠EAF = {val}°\", \"labelZh\": \"半角恒定角 (45.0°)\", \"labelEn\": \"Half Angle Invariant (45.0°)\"}]}}",
