    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"d1\", \"nameZh\": \"折纸多余背景折痕干扰\", \"nameEn\": \"Origami Crease Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [0, 8], \"to\": [10, 0], \"color\": \"var(--border-subtle)\"}]}], \"coreSkeleton\": {\"nameZh\": \"勾股折叠轴对称保距与二次方程骨架\", \"nameEn\": \"Pythagorean Fold Equation Skeleton\", \"primaryElements\": [\"A\", \"B\", \"E\", \"A_prime\"], \"invariants\": [{\"id\": \"telemetry_pythagorean_eq\", \"type\": \"relation\", \"deps\": [\"B\", \"A_prime\", \"E\"], \"formula\": \"y^2 + {x0}^2 = (8-y)^2 \\\\implies 16y = 64 - {x0}^2\", \"labelZh\": \"勾股方程: BE^2 + BA'^2 = A'E^2\", \"labelEn\": \"Pythagorean Equation\", \"isConstant\": false}, {\"id\": \"telemetry_algebraic_sol\", \"type\": \"relation\", \"deps\": [\"E\"], \"formula\": \"y = \\\\frac{64 - {x0}^2}{16} = {val}\", \"labelZh\": \"方程精确解 BE = y\", \"labelEn\": \"Exact Solution BE = y\", \"isConstant\": false}, {\"id\": \"telemetry_verification\", \"type\": \"relation\", \"deps\": [\"B\", \"A_prime\", \"E\"], \"formula\": \"y^2 + x_0^2 - (8-y)^2 \\\\equiv 0.000\", \"labelZh\": \"代数闭环验证\", \"labelEn\": \"Algebraic Closure Check\", \"isConstant\": true}]}}",
