    "carrier_morphing_json": "{\"options\": [{\"id\": \"linear_equation_inequality_plane\", \"nameZh\": \"双线交点与不等式上方区域载体\", \"nameEn\": \"Linear Equation and Inequality Carrier\", \"isAxis\": true, \"points\": [{\"id\": \"O\", \"name\": \"O\", \"x\": 0, \"y\": 0, \"color\": \"#64748b\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P_intersect\", \"name\": \"交点P\", \"x\": 2, \"y\": 2, \"color\": \"#f59e0b\", \"size\": 6, \"isFixed\": false}, {\"id\": \"A1\", \"name\": \"A1\", \"x\": 1, \"y\": 0, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": false}, {\"id\": \"B1\", \"name\": \"B1\", \"x\": 0, \"y\": -2, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": false}, {\"id\": \"A2\", \"name\": \"A2\", \"x\": 4, \"y\": 0, \"color\": \"#818cf8\", \"size\": 4, \"isFixed\": false}, {\"id\": \"B2\", \"name\": \"B2\", \"x\": 0, \"y\": 4, \"color\": \"#818cf8\", \"size\": 4, \"isFixed\": false}]}, {\"id\": \"parallel_shift_plane\", \"nameZh\": \"平行移动截距可变载体\", \"nameEn\": \"Parallel Shift Carrier\", \"isAxis\": true, \"points\": [{\"id\": \"O\", \"name\": \"O\", \"x\": 0, \"y\": 0, \"color\": \"#64748b\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P_intersect\", \"name\": \"P\", \"x\": 3, \"y\": 1, \"color\": \"#f59e0b\", \"size\": 5, \"isFixed\": false}, {\"id\": \"A1\", \"name\": \"A1\", \"x\": 0, \"y\": 2, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": false}, {\"id\": \"A2\", \"name\": \"A2\", \"x\": 0, \"y\": -1, \"color\": \"#818cf8\", \"size\": 4, \"isFixed\": false}]}], \"default\": \"linear_equation_inequality_plane\"}",
    "parameter_morphing_json": "{\"description\": \"两一次函数斜率与截距滑块\", \"sliders\": [{\"id\": \"slope_k1\", \"nameZh\": \"直线 L1 斜率 k₁\", \"nameEn\": \"Line 1 Slope k1\", \"min\": -3.0, \"max\": 3.0, \"default\": 2.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"intercept_b1\", \"nameZh\": \"直线 L1 截距 b₁\", \"nameEn\": \"Line 1 Intercept b1\", \"min\": -5.0, \"max\": 5.0, \"default\": -2.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"slope_k2\", \"nameZh\": \"直线 L2 斜率 k₂\", \"nameEn\": \"Line 2 Slope k2\", \"min\": -3.0, \"max\": 3.0, \"default\": -1.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"intercept_b2\", \"nameZh\": \"直线 L2 截距 b₂\", \"nameEn\": \"Line 2 Intercept b2\", \"min\": -5.0, \"max\": 5.0, \"default\": 4.0, \"step\": 0.5, \"unit\": \"\"}]}",
