    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"d1\", \"nameZh\": \"不等式阴影半平面干扰\", \"nameEn\": \"Shaded Half-plane Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [-6, 0], \"to\": [6, 0], \"color\": \"var(--border-subtle)\"}]}], \"coreSkeleton\": {\"nameZh\": \"一次函数图象交点与不等式解集骨架\", \"nameEn\": \"Linear Function Equation Inequality Skeleton\", \"primaryElements\": [\"P_intersect\", \"A1\", \"B1\", \"A2\", \"B2\"], \"invariants\": [{\"id\": \"telemetry_equation_root\", \"type\": \"relation\", \"deps\": [\"L1\", \"L2\"], \"formula\": \"k1*x + b1 = k2*x + b2 \\\\implies x_0 = \\\\frac{b2-b1}{k1-k2} = {x0}\", \"labelZh\": \"方程的解 (交点横坐标)\", \"labelEn\": \"Equation Root (Intersection X)\", \"isConstant\": false}, {\"id\": \"telemetry_intersection_point\", \"type\": \"relation\", \"deps\": [\"P_intersect\"], \"formula\": \"P(x_0, y_0) = ({x0}, {y0})\", \"labelZh\": \"交点坐标\", \"labelEn\": \"Intersection Point\", \"isConstant\": false}, {\"id\": \"telemetry_inequality_solution\", \"type\": \"relation\", \"deps\": [\"L1\", \"L2\"], \"formula\": \"y_1 > y_2 \\\\iff x \\\\in ({x0}, +\\\\infty)\", \"labelZh\": \"不等式解集 (高在上方图象)\", \"labelEn\": \"Inequality Solution Set\", \"isConstant\": false}]}}",
