    "posture_morphing_json": "{\"modes\": [{\"id\": \"standard\", \"nameZh\": \"标准经济图表态\", \"nameEn\": \"Standard Economic Chart\", \"rotationDeg\": 0, \"reflected\": false}, {\"id\": \"zoomed\", \"nameZh\": \"局部放大临界区\", \"nameEn\": \"Zoomed Critical Region\", \"rotationDeg\": 0, \"reflected\": false}], \"default\": \"standard\"}",
    "camouflage_xray_json": "{\"distractorLayers\": [], \"coreSkeleton\": {\"nameZh\": \"分段函数最优化决策平衡点骨架\", \"nameEn\": \"Piecewise Optimization Equilibrium Skeleton\", \"primaryElements\": [\"P_crit\", \"B_start\", \"Curr_A\", \"Curr_B\"], \"invariants\": [{\"id\": \"telemetry_cost_a\", \"type\": \"relation\", \"deps\": [\"plan_A\"], \"formula\": \"Cost_A({x}) = 2.4 \\\\times {x} = {costA} \\\\text{ 元}\", \"labelZh\": \"网约车费用\", \"labelEn\": \"Rideshare Cost\", \"isConstant\": false}, {\"id\": \"telemetry_cost_b\", \"type\": \"relation\", \"deps\": [\"plan_B\"], \"formula\": \"Cost_B({x}) = {costB} \\\\text{ 元}\", \"labelZh\": \"出租车费用\", \"labelEn\": \"Taxi Cost\", \"isConstant\": false}, {\"id\": \"telemetry_optimal_choice\", \"type\": \"relation\", \"deps\": [\"plan_A\", \"plan_B\"], \"formula\": \"Decision: \\\\text{x < 11 选网约车更省; x > 11 选出租车更省; x=11 费用相同 (26.4元)}\", \"labelZh\": \"最优化决策建议\", \"labelEn\": \"Optimal Decision Advice\", \"isConstant\": false}]}}",
