    "carrier_morphing_json": "{\"default\": \"parabola_secant\", \"options\": [{\"id\": \"parabola_secant\", \"nameZh\": \"抛物线割线铅垂高载体\", \"nameEn\": \"Parabola Secant Plumb Height Carrier\", \"isAxis\": true, \"points\": [{\"id\": \"A\", \"name\": \"A\", \"x\": -1.0, \"y\": 0.0, \"color\": \"var(--text-primary, #38bdf8)\", \"size\": 4, \"isFixed\": true}, {\"id\": \"B\", \"name\": \"B\", \"x\": 3.0, \"y\": 0.0, \"color\": \"var(--text-primary, #38bdf8)\", \"size\": 4, \"isFixed\": true}, {\"id\": \"P\", \"name\": \"P\", \"x\": 1.0, \"y\": 4.0, \"color\": \"var(--ios-orange, #f59e0b)\", \"size\": 5, \"isFixed\": false}, {\"id\": \"Q\", \"name\": \"Q\", \"x\": 1.0, \"y\": 0.0, \"color\": \"var(--ios-indigo, #818cf8)\", \"size\": 4, \"isFixed\": false}]}]}",
