    "parameter_morphing_json": "{\"description\": \"瓜豆原理主从动点具名滑块\", \"sliders\": [{\"id\": \"slider_phi\", \"nameZh\": \"主动点运动极角 φ\", \"nameEn\": \"Master Point Polar Angle φ\", \"min\": 0, \"max\": 360, \"default\": 60, \"step\": 5, \"unit\": \"°\"}, {\"id\": \"slider_alpha\", \"nameZh\": \"联动旋转角 α\", \"nameEn\": \"Rotation Coupling Angle α\", \"min\": 0, \"max\": 180, \"default\": 60, \"step\": 10, \"unit\": \"°\"}, {\"id\": \"slider_ratio_k\", \"nameZh\": \"位似相似比 k\", \"nameEn\": \"Homothetic Ratio k\", \"min\": 0.3, \"max\": 2.0, \"default\": 0.8, \"step\": 0.1, \"unit\": \"\"}]}",
