    "parameter_morphing_json": "{\"description\": \"反比例函数面积不变性具名滑块\", \"sliders\": [{\"id\": \"inv_k\", \"nameZh\": \"反比例系数 k\", \"nameEn\": \"Inverse Coeff k\", \"min\": 2.0, \"max\": 12.0, \"default\": 6.0, \"step\": 1.0, \"unit\": \"\"}, {\"id\": \"x_pos\", \"nameZh\": \"动点横坐标 t\", \"nameEn\": \"Point X Coord t\", \"min\": 0.5, \"max\": 8.0, \"default\": 3.0, \"step\": 0.5, \"unit\": \"\"}, {\"id\": \"secant_m\", \"nameZh\": \"割线斜率 m\", \"nameEn\": \"Secant Slope m\", \"min\": -2.0, \"max\": 2.0, \"default\": -0.5, \"step\": 0.1, \"unit\": \"\"}]}",
