    "posture_morphing_json": "{\"default\": \"standard\", \"modes\": [{\"id\": \"standard\", \"nameZh\": \"标准观察角 (主/左/俯/3D四分格)\", \"nameEn\": \"Standard Four-Quadrant View\", \"rotationDeg\": 0, \"reflected\": false}, {\"id\": \"front_priority\", \"nameZh\": \"主视图高平齐对准\", \"nameEn\": \"Front View Priority\", \"rotationDeg\": 0, \"reflected\": true}, {\"id\": \"top_priority\", \"nameZh\": \"俯视图基底标数对准\", \"nameEn\": \"Top View Priority\", \"rotationDeg\": 90, \"reflected\": false}]}",
    "camouflage_xray_json": "{\"distractorLayers\": [], \"coreSkeleton\": {\"nameZh\": \"正投影高平齐长对正骨架\", \"nameEn\": \"Orthographic Alignment Invariants\", \"primaryElements\": [], \"invariants\": [{\"id\": \"inv_total_blocks\", \"type\": \"formula\", \"formula\": \"slider_h11 + slider_h12 + slider_h21 + slider_h22\", \"labelZh\": \"正方体积木总块数 N\"}, {\"id\": \"inv_front_proj\", \"type\": \"relation\", \"deps\": [], \"formula\": \"长对正 · 高平齐 · 宽相等\", \"labelZh\": \"正投影三等公理\", \"labelEn\": \"Orthographic Principle\", \"isConstant\": true}, {\"id\": \"inv_left_proj\", \"type\": \"relation\", \"deps\": [], \"formula\": \"左视图行高 = max(h_row)\", \"labelZh\": \"左视图行投影高度\", \"labelEn\": \"Left View Row Projection\", \"isConstant\": true}]}}",
