    "model_brief_zh": "中考几何终极压轴，双直角三角形设高或公共边列三角方程，仰角俯角测量建模。",
    "model_brief_en": "The ultimate finale in high school entrance exam geometry; setting up trigonometric equations by introducing altitudes or common sides in double right triangles, and modeling measurements with angles of elevation and depression.",
    "viewbox_spec_json": "{\"xMin\": -10, \"xMax\": 10, \"yMin\": -8, \"yMax\": 8, \"marginPercent\": 15, \"preserveAspectRatio\": true}",
    "carrier_morphing_json": "{\"default\": \"carrier_trig\", \"options\": [{\"id\": \"carrier_trig\", \"nameZh\": \"双直角三角形测高载体\", \"nameEn\": \"Double Right Triangle Altimetry Carrier\", \"points\": [{\"id\": \"C\", \"name\": \"C(大楼底部)\", \"x\": 0, \"y\": 0, \"color\": \"#34c759\", \"size\": 5, \"isFixed\": true}, {\"id\": \"D\", \"name\": \"D(大楼顶部)\", \"x\": 0.0, \"y\": 6.0, \"color\": \"#f59e0b\", \"size\": 5, \"isFixed\": false}, {\"id\": \"B\", \"name\": \"B(近测站)\", \"x\": -6.0, \"y\": 0.0, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": false}, {\"id\": \"A\", \"name\": \"A(远测站)\", \"x\": -10.392, \"y\": 0.0, \"color\": \"#38bdf8\", \"size\": 4, \"isFixed\": false}]}]}",
    "parameter_morphing_json": "{\"description\": \"锐角三角函数综合度量具名滑块\", \"sliders\": [{\"id\": \"slider_h\", \"nameZh\": \"建筑物目标高度 h\", \"nameEn\": \"Building Target Height h\", \"min\": 10.0, \"max\": 100.0, \"default\": 30.0, \"step\": 2.0, \"unit\": \"m\"}, {\"id\": \"slider_alpha\", \"nameZh\": \"远测站仰角 α\", \"nameEn\": \"Station A Elevation α\", \"min\": 15, \"max\": 45, \"default\": 30, \"step\": 5, \"unit\": \"°\"}, {\"id\": \"slider_beta\", \"nameZh\": \"近测站仰角 β\", \"nameEn\": \"Station B Elevation β\", \"min\": 35, \"max\": 75, \"default\": 45, \"step\": 5, \"unit\": \"°\"}]}",
    "posture_morphing_json": "{\"default\": \"standard\", \"modes\": [{\"id\": \"standard\", \"nameZh\": \"双直角测高标准同侧态\", \"nameEn\": \"Same Side Double Right Triangle\", \"rotationDeg\": 0, \"reflected\": false}, {\"id\": \"opposite_side\", \"nameZh\": \"双测站分居大楼两侧态\", \"nameEn\": \"Opposite Sides Double Right Triangle\", \"rotationDeg\": 0, \"reflected\": true}, {\"id\": \"slope_model\", \"nameZh\": \"斜坡与路基边坡综合度量态\", \"nameEn\": \"Slope Altimetry Model\", \"rotationDeg\": 30, \"reflected\": false}]}",
    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"sight_distractor\", \"nameZh\": \"视线仰角辅助延长线干扰\", \"nameEn\": \"Sight Line Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [-12, 0], \"to\": [2, 0], \"color\": \"#64748b\"}]}], \"coreSkeleton\": {\"nameZh\": \"双直角公共高三角方程解算骨架\", \"nameEn\": \"Dual Right Triangle Trigonometric Solver\", \"primaryElements\": [\"C\", \"D\", \"A\", \"B\"], \"highlightColor\": \"#0071e3\", \"invariants\": [{\"id\": \"inv_station_dist\", \"type\": \"formula\", \"formula\": \"slider_h * (1 / tan(slider_alpha * 3.14159 / 180) - 1 / tan(slider_beta * 3.14159 / 180))\", \"labelZh\": \"测站位移距离 AB = d (m)\"}, {\"id\": \"inv_tan_alpha\", \"type\": \"formula\", \"formula\": \"tan(slider_alpha * 3.14159 / 180)\", \"labelZh\": \"远测站正切比值 tan α\"}, {\"id\": \"inv_tan_beta\", \"type\": \"formula\", \"formula\": \"tan(slider_beta * 3.14159 / 180)\", \"labelZh\": \"近测站正切比值 tan β\"}, {\"id\": \"inv_height_identity\", \"type\": \"formula\", \"formula\": \"slider_h\", \"labelZh\": \"反求大楼真实高度 h (m)\", \"isConstant\": true}]}}",
