    "camouflage_xray_json": "{\"distractorLayers\": [{\"id\": \"game_distractor\", \"nameZh\": \"抽奖转盘边界干扰\", \"nameEn\": \"Lottery Distractor\", \"type\": \"lines\", \"items\": [{\"from\": [-7, -3], \"to\": [-7, 3], \"color\": \"#64748b\"}, {\"from\": [7, -3], \"to\": [7, 3], \"color\": \"#64748b\"}]}], \"coreSkeleton\": {\"nameZh\": \"古典概型树状图与大数收敛骨架\", \"nameEn\": \"Classical Probability Tree & LLN Convergence\", \"primaryElements\": [\"Root\", \"Stage1_A\", \"Stage1_B\", \"Leaf_AA\", \"TheoryP\"], \"highlightColor\": \"#0071e3\", \"invariants\": [{\"id\": \"inv_prob_sum\", \"type\": \"relation\", \"deps\": [\"Stage1_A\", \"Stage1_B\"], \"formula\": \"P(A) + P(B) = 1.00\", \"labelZh\": \"完备事件概率和恒为 1.00\", \"labelEn\": \"Sum of Probabilities Equals 1.00\", \"isConstant\": true}, {\"id\": \"inv_joint_prob\", \"type\": \"formula\", \"formula\": \"slider_p * (1 - slider_p)\", \"labelZh\": \"两步独立联合概率 P(A∩B) = P(A)·P(B)\"}, {\"id\": \"inv_large_numbers\", \"type\": \"relation\", \"deps\": [\"TheoryP\", \"Sample3\"], \"formula\": \"lim_{N→∞} f_N(A) = P(A)\", \"labelZh\": \"大数定律：试验频率逼近理论概率\", \"labelEn\": \"Law of Large Numbers: Frequency Converges to Probability\", \"isConstant\": true}]}}",
